    /* MONO ADV radial launcher: eight original application destinations. */
  const RADIAL_APPS = ['blazer','lime','moments','bbs','schedule','gallery','worldbook','settings'];
  function placeWheel() {
    if (!SS.wheel || !SS.wheelOpen) return;
    const vp = viewport();
    const size = Math.min(370, vp.w - 20, vp.h - 72);
    const cx = SS.orbPos.x + ORB_W / 2, cy = SS.orbPos.y + ORB_H / 2;
    const x = Math.max(vp.x + 10, Math.min(cx - size / 2, vp.x + vp.w - size - 10));
    const y = Math.max(vp.y + 10, Math.min(cy - size / 2, vp.y + vp.h - size - 56));
    writePos(SS.wheel, x, y, size, size);
    writePos(SS.wheelBackdrop, vp.x, vp.y, vp.w, vp.h);
  }
  function closeWheel(restoreFocus) {
    if (!SS.wheelOpen) return;
    SS.wheelOpen = false;
    SS.wheel.classList.remove('on');
    SS.wheelBackdrop.classList.remove('on');
    SS.orb.setAttribute('aria-expanded', 'false');
    if (restoreFocus) {
      const target = SS.focusBeforeWheel && SS.focusBeforeWheel.isConnected ? SS.focusBeforeWheel : SS.orb;
      try { target.focus({preventScroll:true}); } catch (_) {}
    }
  }
  function toggleWheel(keyboard) {
    if (SS.destroyed) return;
    if (SS.wheelOpen) { closeWheel(true); return; }
    clearOrbTip();
    SS.focusBeforeWheel = HD.activeElement;
    SS.wheelOpen = true;
    SS.wheel.classList.add('on');
    SS.wheelBackdrop.classList.add('on');
    SS.orb.setAttribute('aria-expanded', 'true');
    SS.wheel.querySelector('.mono-wheel-caption b').textContent = '选择终端应用';
    placeWheel();
    if (keyboard) SS.wheel.querySelector('.mono-sector').focus();
  }
  async function openPhoneApp(appId) {
    if (appId !== 'home' && !RADIAL_APPS.includes(appId)) return;
    closeWheel(false);
    await show();
    if (!SS.visible || !SS.booted || SS.destroyed) return;
    try {
      const iw = SS.iframe && SS.iframe.contentWindow;
      if (!iw) return;
      if (typeof iw.goHome === 'function') iw.goHome();
      if (appId !== 'home' && typeof iw.openApp === 'function') iw.openApp(appId);
      iw.focus();
    } catch(e) { console.warn('[Hagun-Mono-Terminal] Navigation:', e); }
  }
