    HD.body.appendChild(SS.wheel);
    SS.wheelBackdrop.addEventListener('pointerdown', () => closeWheel(true));
    SS.wheel.querySelector('.mono-wheel-close').addEventListener('click', () => closeWheel(true));
    SS.wheel.querySelector('.mono-core').addEventListener('click', () => openPhoneApp('home'));
    SS.orb.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggleWheel(true); }
    });
    const items = Array.from(SS.wheel.querySelectorAll('.mono-sector'));
    items.forEach((item,index) => {
      function select() {
        SS.wheel.querySelector('.mono-wheel-caption b').textContent = item.getAttribute('data-label');
        items.forEach(it => it.setAttribute('tabindex',it === item ? '0' : '-1'));
      }
      item.addEventListener('pointerenter', select);
      item.addEventListener('focus', select);
      item.addEventListener('click', () => openPhoneApp(item.getAttribute('data-app')));
      item.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openPhoneApp(item.getAttribute('data-app')); return; }
        let next=index;
        if (e.key === 'ArrowRight' || e.key === 'ArrowDown') next=(index+1)%items.length;
        else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') next=(index+items.length-1)%items.length;
        else if (e.key === 'Home') next=0;
        else if (e.key === 'End') next=items.length-1;
        else return;
        e.preventDefault(); items[next].focus();
      });
    });
    const escape = (e) => {
      if (e.key === 'Escape') {
        if (SS.wheelOpen) { e.preventDefault(); closeWheel(true); }
        else if (SS.visible && !(e.target && /INPUT|TEXTAREA|SELECT/.test(e.target.tagName))) hide();
      }
    };
    const outside = (e) => {
      if (SS.wheelOpen && !SS.wheel.contains(e.target) && !SS.orb.contains(e.target)) closeWheel(false);
    };
    HD.addEventListener('keydown',escape);
    HD.addEventListener('pointerdown',outside,true);
    SS.disposers.push(() => HD.removeEventListener('keydown',escape));
    SS.disposers.push(() => HD.removeEventListener('pointerdown',outside,true));
  }

  /* 拖拽与缩放引擎 */


  function bindDrag() {
    const bar = SS.host.querySelector('.bar');
    const rsz = SS.host.querySelector('.rsz');
    let st = null;

    function down(e, kind) {
      if (SS.mode === 'drawer') return;
      if (e.button !== undefined && e.button !== 0) return;
      if (e.target && e.target.closest && e.target.closest('button')) return;
      try { e.currentTarget.setPointerCapture && e.currentTarget.setPointerCapture(e.pointerId); } catch(_) {}
      st = { kind, sx: e.clientX, sy: e.clientY, r: { ...SS.rect } };
      SS.host.classList.add('busy');
    }

    function move(e) {
      if (!st) return;
      const dx = e.clientX - st.sx, dy = e.clientY - st.sy, vp = viewport();
      HW.requestAnimationFrame(() => {
        if (!st) return;
        if (st.kind === 'drag') {
          applyRect(clampRect({ ...st.r, x: st.r.x + dx, y: st.r.y + dy }, vp));
        } else {
          applyRect(clampRect({ ...st.r, w: st.r.w + dx, h: st.r.h + dy }, vp));
        }
      });
    }

    function up() {
      if (!st) return;
      st = null;
      SS.host.classList.remove('busy');
      LS.set('rk:rect', SS.rect);
    }

    bar.addEventListener('pointerdown', e => down(e, 'drag'));
    rsz.addEventListener('pointerdown', e => down(e, 'rsz'));
    HD.addEventListener('pointermove', move);
    HD.addEventListener('pointerup', up);
    HD.addEventListener('pointercancel', up);

    SS.disposers.push(() => {
      HD.removeEventListener('pointermove', move);
      HD.removeEventListener('pointerup', up);
      HD.removeEventListener('pointercancel', up);
    });

    /* 悬浮球拖拽与吸边 */
    let ost = null, moved = false;
    SS.orb.addEventListener('pointerdown', e => {
      if (e.button !== undefined && e.button !== 0) return;
      if (e.cancelable) e.preventDefault();
      e.stopPropagation();
      try { SS.orb.setPointerCapture && SS.orb.setPointerCapture(e.pointerId); } catch(_) {}
      ost = { sx: e.clientX, sy: e.clientY, x: SS.orbPos.x, y: SS.orbPos.y };
      moved = false;
    });

    SS.orb.addEventListener('pointermove', e => {
      if (!ost) return;
      const dx = e.clientX - ost.sx, dy = e.clientY - ost.sy;
      if (!moved && Math.hypot(dx, dy) > 8) moved = true;
      if (moved) placeOrb(clampOrb(ost.x + dx, ost.y + dy));
    });

    SS.orb.addEventListener('pointerup', e => {
      if (e.cancelable) e.preventDefault();
      e.stopPropagation();
      if (!ost) return;
      if (moved) {
        placeOrb(clampOrb(SS.orbPos.x, SS.orbPos.y));
        LS.set('rk:orb', { x: SS.orbPos.x, y: SS.orbPos.y });
      } else {
        clearOrbTip();
      }
      ost = null;
    });

    SS.orb.addEventListener('click', e => {
      e.preventDefault(); e.stopPropagation();
      if (!moved) toggleWheel();
      moved = false;
    });
    SS.orb.addEventListener('pointercancel', () => { ost = null; moved = true; });
  }

  function toggle() { SS.visible ? hide() : show(); }

  async function show() {
    if (SS.destroyed) return;
    closeWheel(false);
    clearOrbTip();
    setMode(preferDrawer() ? 'drawer' : 'floating');
    SS.host.classList.add('on');
    SS.visible = true;
    SS.orb.style.visibility = 'hidden';
    refreshStatePanel();
    if (!SS.booted) await mountPhone();
    if (!SS.destroyed && SS.visible) {
      emit({ type: 'show', reset: true });
      clearInterval(readTimer);
      // 代码直写变量不一定产生 MVU 事件；只在终端展开时核对已保存数据。
      readTimer = setInterval(() => emit({ type: 'poll' }), 1000);
    }
  }

  function hide() {
    closeWheel(false);
    SS.host.classList.remove('on');
    SS.visible = false;
    clearInterval(readTimer);
    SS.orb.style.visibility = '';
    try { SS.orb.focus({ preventScroll: true }); } catch (_) {}
  }

