ck=\"goBack()\">\u003ci class=\"ti ti-chevron-left\">\u003c/i>\u003c/button>\n      \u003cspan class=\"t\">破军 BBS // 选拔战板\u003c/span>\n      \u003cspan class=\"act\">\u003cbutton onclick=\"refreshBbs()\">\u003ci class=\"ti ti-refresh\">\u003c/i> 刷新\u003c/button>\u003c/span>\n    \u003c/div>\n    \u003cdiv class=\"body\" id=\"bbs-body\">\u003c/div>\n  \u003c/div>\n\n  \u003c!-- 6. 选拔赛程 (Schedule) -->\n  \u003cdiv class=\"scr\" id=\"scr-schedule\">\n    \u003cdiv class=\"apphead\">\n      \u003cbutton class=\"back\" onclick=\"goBack()\">\u003ci class=\"ti ti-chevron-left\">\u003c/i>\u003c/button>\n      \u003cspan class=\"t\">选拔赛程与决斗\u003c/span>\n    \u003c/div>\n    \u003cdiv class=\"body\" id=\"schedule-body\">\u003c/div>\n  \u003c/div>\n\n  \u003c!-- 7. 灵装画廊 (Gallery) -->\n  \u003cdiv class=\"scr\" id=\"scr-gallery\">\n    \u003cdiv class=\"apphead\">\n      \u003cbutton class=\"back\" onclick=\"goBack()\">\u003ci class=\"ti ti-chevron-left\">\u003c/i>\u003c/button>\n      \u003cspan class=\"t\">灵装与战术相册\u003c/span>\n    \u003c/div>\n    \u003cdiv class=\"body\" id=\"gallery-body\">\u003c/div>\n  \u003c/div>\n\n  \u003c!-- 8. 世界之理 (Worldbook) -->\n  \u003cdiv class=\"scr\" id=\"scr-worldbook\">\n    \u003cdiv class=\"apphead\">\n      \u003cbutton class=\"back\" onclick=\"goBack()\">\u003ci class=\"ti ti-chevron-left\">\u003c/i>\u003c/button>\n      \u003cspan class=\"t\">世界之理 (世界书)\u003c/span>\n    \u003c/div>\n    \u003cdiv class=\"body\" id=\"worldbook-body\">\u003c/div>\n  \u003c/div>\n\n  \u003c!-- 9. 终端配置 (Settings) -->\n  \u003cdiv class=\"scr\" id=\"scr-settings\">\n    \u003cdiv class=\"apphead\">\n      \u003cbutton class=\"back\" onclick=\"goBack()\">\u003ci class=\"ti ti-chevron-left\">\u003c/i>\u003c/button>\n      \u003cspan class=\"t\">终端配置\u003c/span>\n    \u003c/div>\n    \u003cdiv class=\"body\" id=\"settings-body\">\u003c/div>\n  \u003c/div>\n\n\u003c/div>\n\n\u003c!-- 底部 Homebar -->\n\u003cdiv id=\"homebar\">\n\u003cbutton onclick=\"goBack()\" ti