  async function mountVia(html, mode) {
    if (SS.destroyed) throw new Error('终端已销毁，已取消挂载');
    const f = HD.createElement('iframe');
    f.setAttribute('title', '破军战术终端');
    SS.host.appendChild(f);
    SS.iframe = f;
    try {
      await new Promise((res, rej) => {
        let settled = false;
        let timeout;
        const finish = error => {
          if (settled) return;
          settled = true;
          clearTimeout(timeout);
          f.onload = null;
          if (SS.cancelMount === cancel) SS.cancelMount = null;
          error ? rej(error) : res();
        };
        const cancel = () => finish(new Error('终端已销毁，已取消挂载'));
        SS.cancelMount = cancel;
        timeout = setTimeout(() => finish(new Error(mode + ' 超时')), mode === 'blob' ? 3000 : 5000);
        f.onload = () => finish();
        try {
          if (mode === 'blob') {
            SS.blobUrl = URL.createObjectURL(new Blob([html], { type: 'text/html' }));
            f.src = SS.blobUrl;
          } else {
            f.srcdoc = html;
          }
        } catch (error) {
          finish(error);
        }
      });
      if (SS.destroyed || SS.iframe !== f) throw new Error('终端已销毁或挂载已失效');
      const boot = f.contentWindow && f.contentWindow.RKBoot;
      if (typeof boot !== 'function') throw new Error('RKBoot 缺失（' + mode + '）');
      boot(makeBridge());
    } catch(e) {
      try { f.remove(); } catch(_) {}
      if (SS.iframe === f) SS.iframe = null;
      if (mode === 'blob' && SS.blobUrl) { try { HW.URL.revokeObjectURL(SS.blobUrl); } catch(_) {} SS.blobUrl = null; }
      throw e;
    }
  }

  async function mountPhone() {
    if (SS.booted || SS.destroyed) return;
    if (SS.mounting) return SS.mounting;
    SS.mounting = (async () => {
      const html = embeddedPhoneHtml();
      try {
        try { await mountVia(html, 'srcdoc'); }
        catch (e1) { if (SS.destroyed) return; await mountVia(html, 'blob'); }
        if (!SS.destroyed) SS.booted = true;
      } catch (e) {
        if (SS.destroyed) return;
        console.error('[Hagun-Mono-Terminal] Mount failed:', e);
        showOrbTip('终端未能加载', '收起后再次打开可重试；请查看浏览器控制台。');
      } finally { SS.mounting = null; }
    })();
    return SS.mounting;
  }

  /* 桥接对象 (Bridge) */
  function readSnapshot() {
    return createTerminalStateReader(fn('getChatMessages'), () => {
      const st = HW.SillyTavern || window.SillyTavern;
      return st && typeof st.getContext === 'function' ? st.getContext() : null;
    })();
  }

  const updateCbs = [];
  let readTimer;
  function emit(ev) {
    updateCbs.forEach(cb => { try { cb(ev); } catch(_) {} });
  }

  function makeBridge() {
    return {
      version: BUILD_VERSION,
      relationshipRules: RELATIONSHIP_SCORING,
      supportStage,
      getSnapshot: async () => readSnapshot(),
      getStat: async () => readSnapshot().state,
      onUpdate: (cb) => {
        updateCbs.push(cb);
        return () => { const index = updateCbs.indexOf(cb); if (index !== -1) updateCbs.splice(index, 1); };
      },
      setOrbBadge: (n) => {
        const b = SS.orb && SS.orb.querySelector('.b');
        if (!b) return;
        SS.badge = n | 0;
        b.textContent = SS.badge > 99 ? '99+' : String(SS.badge);
        b.style.display = SS.badge > 0 ? 'block' : 'none';
      },
      notify: (p) => {
        p = p || {};
        if (!p.title && !p.body) { clearOrbTip(); return; }
        if (SS.visible) return;
        showOrbTip(p.title, p.body);
      },
      ui: {
        close: hide,
        recenter: () => recenter(),
        openStoryControls: () => { if (statePanel) { statePanel.open = true; refreshStatePanel(); } }
      }
    };
  }

  /* 宿主事件监听 */
  function wireEvents() {
    const eon = fn('eventOn');
    if (!eon) return;
    const TE = window.tavern_events || {};
    function safeOn(ev, cb) {
      try { const r = eon(ev, cb); r && r.stop && SS.disposers.push(() => r.stop()); } catch(_) {}
    }

    // 使用宿主导出的常量；更新中间态不拿来充当已保存状态。
    for (const name of ['CHAT_CHANGED', 'MESSAGE_SWIPED', 'MESSAGE_SWIPE_DELETED', 'MESSAGE_DELETED', 'MESSAGE_UPDATED', 'MESSAGE_EDITED', 'MESSAGE_RECEIVED', 'CHARACTER_FIRST_MESSAGE_SELECTED']) {
      if (TE[name]) safeOn(TE[name], () => emit({ type: name, reset: true }));
    }
    if (TE.GENERATION_ENDED) safeOn(TE.GENERATION_ENDED, () => emit({ type: 'story-turn' }));
  }

  function onResize() {
    if (SS.visible) setMode(preferDrawer() ? 'drawer' : 'floating');
    placeOrb(clampOrb(SS.orbPos.x, SS.orbPos.y));
    placeOrbTip();
    placeWheel();
  }

  function destroy() {
    if (SS.destroyed) return;
    SS.destroyed = true;
    if (SS.cancelMount) SS.cancelMount();
    clearInterval(readTimer);
    disposeStatePanel();
    updateCbs.length = 0;
    try { SS.wheel && SS.wheel.remove(); SS.wheelBackdrop && SS.wheelBackdrop.remove(); } catch (_) {}
    try { if (HW.RKTacticalToggle === toggle) delete HW.RKTacticalToggle; } catch (_) {}
    while (SS.disposers.length) { try { SS.disposers.pop()(); } catch(_) {} }
    try { HW.removeEventListener('resize', onResize); } catch(_) {}
    try { SS.iframe && SS.iframe.remove(); } catch(_) {}
    try { SS.host && SS.host.remove(); } catch(_) {}
    try { SS.orb && SS.orb.remove(); } catch(_) {}
    try { SS.style && SS.style.remove(); } catch(_) {}
    try { SS.blobUrl && HW.URL.revokeObjectURL(SS.blobUrl); } catch(_) {}
    try { delete HW[SLOT]; } catch(_) {}
  }

    // This view and its token are disposable. MVU remains the only saved story state.
  let statePanel = null;
  let stateCapture = null;
  let panelBusy = false;
  let panelRequest = 0;
  const panelChapters = ['序章', '第一章', '第二章', '第三章', '第四章', '终章'];

  function stateService() {
    const service = window.RakudaiStateController;
    if (!service || typeof service.capture !== 'function' || typeof service.transition !== 'function') {
      throw new Error('剧情状态服务尚未就绪，请刷新后重试。');
    }
    return service;
  }

  function panelText(selector, value) {
    const node = statePanel && statePanel.querySelector(selector);
    if (node) node.textContent = value;
  }

  function updatePanelActions() {
    if (!statePanel) return;
    const state = stateCapture && stateCapture.state;
    const system = state && state.系统 || {};
    const scene = state && state.场景 || {};
    const select = statePanel.querySelector('select');
    const chapter = scene.当前章 === '待选择' ? select.value : scene.当前章;
    const ready = !panelBusy && !!stateCapture && system.开局状态 === '已建档' && system.主角模式 !== '未选择' && scene.当前卷 === 1;
    const located = typeof scene.时间 === 'string' && scene.时间.trim() && typeof scene.地点 === 'string' && scene.地点.trim();
    select.disabled = panelBusy || !stateCapture || scene.当前章 !== '待选择';
    statePanel.querySelector('[data-story-action="refresh"]').disabled = panelBusy;
    statePanel.querySelector('[data-story-action="start"]').disabled = !ready || scene.阶段 !== '未开始' || !located || !panelChapters.includes(chapter);
    statePanel.querySelector('[data-story-action="end"]').disabled = !ready || scene.阶段 !== '进行中';
    statePanel.querySelector('[data-story-action="next"]').disabled = !ready || scene.阶段 !== '已结束' || scene.当前章 === '终章';
    statePanel.setAttribute('aria-busy', String(panelBusy));
  }

  function renderStatePanel() {
    const state = stateCapture && stateCapture.state;
    const system = state && state.系统 || {};
    const scene = state && state.场景 || {};
    panelText('[data-story-summary]', '第一卷剧情 · ' + (scene.当前章 || '未读取') + ' / ' + (scene.阶段 || '未读取'));
    panelText('[data-story-system]', '系统：' + (system.开局状态 || '未读取') + ' · ' + (system.主角模式 || '未选择'));
    panelText('[data-story-scene]', '场景：' + (scene.当前卷 === 1 ? '第一卷' : '卷数未确认') + ' · ' + (scene.当前章 || '未读取') + ' · ' + (scene.阶段 || '未读取'));
    panelText('[data-story-location]', '时间：' + (scene.时间 || '未确认') + '　地点：' + (scene.地点 || '未确认'));
    if (panelChapters.includes(scene.当前章)) statePanel.querySelector('select').value = scene.当前章;
    let hint = '按钮只确认剧情阶段；事件结果仍依据实际对话记录。';
    if (system.开局状态 !== '已建档') hint = '请先完成建档，再确认时间、地点并开始剧情。';
    else if (!scene.时间 || !scene.地点) hint = '请先在聊天中确认本章时间和地点，再开始剧情。';
    else if (scene.当前章 === '待选择') hint = '选择从第一卷的哪一章开始，然后点击“开始本章”。';
    else if (scene.当前章 === '终章' && scene.阶段 === '已结束') hint = '第一卷已结束；此面板不切换到其他卷。';
    panelText('[data-story-hint]', hint);
    updatePanelActions();
  }

  async function refreshStatePanel() {
